  interactive,
  data,
  form,
  sentinelbuild,
}

class ElementMeta {
  final PageElementType type;
  final String label;
  final String description;
  final IconData icon;
  final Color color;
  final ElementCategory category;
  final Map<String, dynamic> defaultConfig;

  const ElementMeta({
    required this.type,
    required this.label,
    required this.description,
    required this.icon,
    required this.color,
    required this.category,
    this.defaultConfig = const {},
  });
}

