ElementMeta metaForType(PageElementType type) {
  return kElementRegistry.firstWhere(
    (m) => m.type == type,
    orElse: () => kElementRegistry.first,
  );
}

List<ElementMeta> metaForCategory(ElementCategory category) {
  return kElementRegistry.where((m) => m.category == category).toList();
}
